<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model;
class QualityKpi extends Model { protected $fillable=['code','name','category','measurement_method','data_source','weight','target_value','value_type','target_numeric','comparison_operator','warning_numeric','measurement_frequency','responsible','is_active']; protected $casts=['target_numeric'=>'decimal:2','warning_numeric'=>'decimal:2','is_active'=>'boolean']; public function measurements(){return $this->hasMany(QualityKpiMeasurement::class)->latest('measured_at');} public function latestMeasurement(){return $this->hasOne(QualityKpiMeasurement::class)->latestOfMany('measured_at');} }
